:root {
  /* Colors */
  --color-ember-signal: #ff5e24;
  --color-sky-canvas: #dceefe;
  --color-paper: #ffffff;
  --color-fog-surface: #f6f8f7;
  --color-frosted-glass: #ffffff66;
  --color-graphite-ink: #232629;
  --color-slate-text: #5c6066;
  --color-pewter-caption: #989ea4;
  --color-ember-bevel: #d54d1a;
  --color-peach-bevel: #ffc7b280;
  --color-cinder-alert: #f4352f;
  --color-cobalt-mark: #2473eb;
  --color-umber-footer: #6c3200;

  /* Typography — Font Families */
  --font-jersey-10: "Jersey 10", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-press-start-2p: "Press Start 2P", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-manrope: "Manrope Variable", "Manrope", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.33;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.55;
  --tracking-caption: -0.18px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 28px;
  --leading-subheading: 1.35;
  --tracking-subheading: 0px;
  --text-heading-sm: 36px;
  --leading-heading-sm: 1.11;
  --tracking-heading-sm: 0px;
  --text-heading: 60px;
  --leading-heading: 0.8;
  --tracking-heading: -1.5px;
  --text-heading-lg: 72px;
  --leading-heading-lg: 0.85;
  --tracking-heading-lg: -1.8px;
  --text-display: 96px;
  --leading-display: 0.7;
  --tracking-display: -2.4px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-96: 96px;
  --spacing-112: 112px;
  --spacing-128: 128px;

  /* Layout */
  --layout-page-max-width: 1216px;
  --layout-section-gap: 96px;
  --layout-card-padding: 16px;
  --layout-element-gap: 16px;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-3xl: 48px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-nav: 6px;
  --radius-buttons: 8px;
  --radius-cards: 12px;
  --radius-inner-tiles: 16px;
  --radius-sections: 24px;
  --radius-images: 24px;
  --radius-alert-banners: 48px;
  --radius-tags: 9999px;
  --radius-pills: 9999px;
  --radius-small-elements: 0px;

  /* Shadows */
  --shadow-subtle: 0px 5px 12px 0px rgba(0,0,0,0.03), 0px 22px 22px 0px rgba(0,0,0,0.03), 0px 49px 30px 0px rgba(0,0,0,0.01);
  --shadow-subtle-2: 0px 0px 0px 4px rgba(244,53,47,0.1);
  --shadow-sm: 0px 2px 4px 0px rgba(15,34,52,0.04), 0px 7px 7px 0px rgba(15,34,52,0.04), 0px 15px 9px 0px rgba(15,34,52,0.02), 0px 27px 11px 0px rgba(15,34,52,0.01);
  --shadow-sm-2: inset 4px 4px 0px 0px rgba(255,199,178,0.5), inset -4px -4px 0px 0px #d54d1a;
  --shadow-md: inset 0px 1px 0px 0px rgba(255,255,255,0.17), inset 0px -1px 0px 0px rgba(255,255,255,0.03), 0px 0px 0px 1px #ff5e24, 0px 1px 2px 0px rgba(4,15,32,0.12), 0px 4px 4px 0px rgba(4,15,32,0.1), 0px 8px 5px 0px rgba(4,15,32,0.06), 0px 15px 6px 0px rgba(4,15,32,0.02);
  --shadow-md-2: 0px 0px 0px 1px #232629, 0px 5px 12px 0px rgba(0,0,0,0.03), 0px 22px 22px 0px rgba(0,0,0,0.03), 0px 49px 30px 0px rgba(0,0,0,0.01);
  --shadow-lg: 0px 25px 50px -12px rgba(0,0,0,0.25);
  --shadow-xl: 24px 24px 0px 0px rgba(0,0,0,0.07);

  /* Surfaces */
  --surface-sky-canvas: #dceefe;
  --surface-frosted-glass: #ffffff66;
  --surface-paper: #ffffff;
  --surface-graphite-ink: #232629;
  --surface-umber-footer: #6c3200;
}

